<?php
declare(strict_types=1);require_once __DIR__.'/includes/bootstrap.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if($_SERVER['REQUEST_METHOD']==='POST')$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);if(!$id||$id<1){flash('error','Invalid transaction ID.');redirect('transactions.php');}$s=$pdo->prepare('SELECT * FROM transactions WHERE id=:id');$s->execute(['id'=>$id]);$t=$s->fetch();if(!$t){flash('error','Transaction not found.');redirect('transactions.php');}$type=$t['type'];$title=$t['title'];$amount=(string)$t['amount'];$category=$t['category'];$date=$t['transaction_date'];$method=$t['payment_method'];$notes=$t['notes'];$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$type=(string)($_POST['type']??'expense');$title=trim((string)($_POST['title']??''));$amount=trim((string)($_POST['amount']??''));$category=(string)($_POST['category']??'');$date=trim((string)($_POST['transaction_date']??''));$method=(string)($_POST['payment_method']??'Cash');$notes=trim((string)($_POST['notes']??''));if(!in_array($type,['income','expense'],true))$errors[]='Choose income or expense.';if($title===''||mb_strlen($title)>100)$errors[]='Title is required (maximum 100 characters).';if(!is_numeric($amount)||(float)$amount<=0)$errors[]='Amount must be greater than zero.';if(!in_array($category,categories($type),true))$errors[]='Choose a valid category.';if(!valid_date($date))$errors[]='Choose a valid date.';if(!in_array($method,['Cash','Bank transfer','Debit card','Credit card','Mobile wallet','Other'],true))$errors[]='Choose a valid payment method.';if(mb_strlen($notes)>1000)$errors[]='Notes are too long.';if(!$errors){$u=$pdo->prepare('UPDATE transactions SET title=:title,type=:type,category=:category,amount=:amount,transaction_date=:date,payment_method=:method,notes=:notes WHERE id=:id');$u->execute(['title'=>$title,'type'=>$type,'category'=>$category,'amount'=>number_format((float)$amount,2,'.',''),'date'=>$date,'method'=>$method,'notes'=>$notes,'id'=>$id]);flash('success','Transaction updated.');redirect('transactions.php?month='.substr($date,0,7));}}
$pageTitle='Edit transaction — ExpenseWise';require __DIR__.'/includes/header.php';?><div class="app-shell"><?php require __DIR__.'/includes/sidebar.php';?><main class="main-area"><header class="topbar"><div><p class="breadcrumb"><a href="transactions.php">Transactions</a> / Edit</p><h1>Keep your records accurate.</h1></div></header><section class="panel form-panel"><span class="eyebrow">UPDATE RECORD</span><h2>Edit transaction</h2><?php if($errors):?><div class="notice error"><ul><?php foreach($errors as $error):?><li><?=e($error)?></li><?php endforeach;?></ul></div><?php endif;?><form method="post" class="transaction-form"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$id?>"><div class="type-toggle"><label><input type="radio" name="type" value="expense" <?=$type==='expense'?'checked':''?>><span>↑ Expense</span></label><label><input type="radio" name="type" value="income" <?=$type==='income'?'checked':''?>><span>↓ Income</span></label></div><label>Transaction title *<input name="title" maxlength="100" required value="<?=e($title)?>"></label><div class="form-grid"><label>Amount (PKR) *<input name="amount" type="number" min="0.01" step="0.01" required value="<?=e($amount)?>"></label><label>Category *<select id="categorySelect" name="category"><?php foreach(categories($type) as $c):?><option <?=$category===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select></label></div><div class="form-grid"><label>Date *<input type="date" name="transaction_date" required value="<?=e($date)?>"></label><label>Payment method<select name="payment_method"><?php foreach(['Cash','Bank transfer','Debit card','Credit card','Mobile wallet','Other'] as $m):?><option <?=$method===$m?'selected':''?>><?=e($m)?></option><?php endforeach;?></select></label></div><label>Notes<textarea name="notes" maxlength="1000" rows="4"><?=e($notes)?></textarea></label><div class="form-actions"><button class="button primary">Save changes →</button><a class="button ghost" href="transactions.php">Cancel</a></div></form></section></main></div><?php require __DIR__.'/includes/footer.php';?>
